INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ce108280114e489bb619d956de0c990e', '795ea9230b88462d97947e861a050c15', 9, 'À bientôt !', 'به زودی می‌بینمت', NULL, NULL, '["خداحافظ برای همیشه", "خوش آمدی", "صبح بخیر", "به زودی می‌بینمت"]', '2026-06-21T09:48:11Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('b1ff2dfb92004a11843729ffbc70ec51', '7d828f93faf446d58f2ef27df63c0e92', 0, 'Nous ___ (avoir - داشتن) deux enfants.', 'avons', 'Nous avons deux enfants.', NULL, '["avez", "avons", "ont", "as"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('bc182485f2fd46c0af40b1d8fb06030f', '7d828f93faf446d58f2ef27df63c0e92', 1, 'Ils ___ (être - بودن) très contents.', 'sont', 'Ils sont très contents.', NULL, '["\u00eates", "sommes", "est", "sont"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('78ca8480b2e345959c3d1802eb303c7b', '7d828f93faf446d58f2ef27df63c0e92', 2, 'Je ___ (aller - رفتن) à l''école.', 'vais', 'Je vais à l''école.', NULL, '["vais", "vas", "va", "allons"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('9082c0fd5dee4f038c2276370931eabf', '7d828f93faf446d58f2ef27df63c0e92', 3, 'Vous ___ (faire - انجام دادن) un bon travail.', 'faites', 'Vous faites un bon travail.', NULL, '["font", "fais", "faites", "faisons"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('107dde2ca644401287129abc4326ee73', '7d828f93faf446d58f2ef27df63c0e92', 4, 'Tu ___ (venir - آمدن) ce soir ?', 'viens', 'Tu viens ce soir ?', NULL, '["vient", "viens", "venez", "viennent"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f0318679a4794ad08ccebc533f2a9ce0', '7d828f93faf446d58f2ef27df63c0e92', 6, 'Nous ___ (lire - خواندن) un livre.', 'lisons', 'Nous lisons un livre.', NULL, '["lisez", "lis", "lisons", "lisent"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('3e3e9bad241942be883c5e2f7167ff6a', '7d828f93faf446d58f2ef27df63c0e92', 7, 'Ils ___ (pouvoir - توانستن) venir demain.', 'peuvent', 'Ils peuvent venir demain.', NULL, '["peux", "peut", "pouvons", "peuvent"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('96b72bb225174972b29c70673194b482', '7d828f93faf446d58f2ef27df63c0e92', 8, 'Je ___ (savoir - دانستن) la réponse.', 'sais', 'Je sais la réponse.', NULL, '["sait", "sais", "savons", "savez"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('75856f324f4842838f703378f1ac5755', '7d828f93faf446d58f2ef27df63c0e92', 9, 'Vous ___ (vouloir - خواستن) du thé ?', 'voulez', 'Vous voulez du thé ?', NULL, '["voulez", "veux", "veut", "voulons"]', '2026-07-03T13:38:55Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('cb887455472745208806d5aae0bbb11d', '0f4317272654459794ab7a70b695e7f1', 0, 'Pourquoi voulez-vous devenir français(e) ?', 'Expliquez que vous vous sentez aujourd''hui plus proche de la France que de votre pays d''origine, citez les valeurs françaises auxquelles vous adhérez, votre projet personnel ou professionnel construit en France, votre mode de vie « à la française », et votre admiration pour la place de la France dans le monde (économie, aéronautique, industrie du luxe, patrimoine culturel).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('7da9609abe2c42228692668debaa66b3', '0f4317272654459794ab7a70b695e7f1', 1, 'À quelle fréquence rentrez-vous dans votre pays d''origine ?', 'Répondez avec un chiffre exact et soyez honnête : l''administration peut vérifier les tampons d''entrée et de sortie sur votre passeport.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('438f038c210c4a8e83df91ad4877e289', '0f4317272654459794ab7a70b695e7f1', 2, 'Pourquoi êtes-vous venu(e) en France pour la première fois ?', 'Répondez selon votre situation réelle : pour les études, pour le travail, ou pour rejoindre votre famille en France.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('381f850f7e1c48289a4b188b5605c4c9', '0f4317272654459794ab7a70b695e7f1', 3, 'Qu''avez-vous trouvé en France que vous n''avez pas dans votre pays d''origine ?', 'Valorisez la France selon votre expérience réelle : par exemple la démocratie, la liberté, la culture, la science.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('2dcfcfaab0e94a8d924cd4f4c5151464', '0f4317272654459794ab7a70b695e7f1', 4, 'Avez-vous des liens personnels et familiaux en France ?', 'Citez tous vos liens familiaux et amicaux en France (cousins, grands-parents, parents, amis) pour montrer que votre intégration repose sur des attaches solides en France.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('5cb6663b1afb4e3c89dfa294060c9176', '0f4317272654459794ab7a70b695e7f1', 5, 'Avez-vous de la famille proche ou lointaine restée dans votre pays d''origine ? Comptez-vous la faire venir en France ?', 'C''est une question piège : vos oncles, cousins, grands-parents et famille éloignée n''ont pas le droit de s''installer en France simplement parce que vous devenez français(e). Répondez honnêtement que vous avez de la famille là-bas mais que vous ne comptez pas la faire venir en France.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('945b203d550d4403b628965d9a110242', '0f4317272654459794ab7a70b695e7f1', 6, 'Où passez-vous vos vacances ?', 'Basez votre réponse sur des villes françaises que vous avez réellement visitées (par exemple Nice, Paris, Lille, Brest, Marseille, Strasbourg).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1bf8a00f439b44978b5ee24f539ad88a', '0f4317272654459794ab7a70b695e7f1', 7, 'Quelles sont les nationalités des personnes de votre entourage ?', 'Montrez que la majorité des personnes qui vous entourent sont françaises et que vous n''êtes pas dans une logique de communautarisme.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('96d7ab3a7eea4cbf96a60eca2692ac35', '0f4317272654459794ab7a70b695e7f1', 8, 'Êtes-vous membre d''une association ? Laquelle, et depuis quand ?', 'Ce n''est pas obligatoire, mais si vous êtes ou avez été membre d''une association (surtout une association d''aide aux personnes démunies), mentionnez-le : c''est un point positif. Attention, faire un don à une association ne fait pas de vous un membre.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('d8dcb572eacd4542ac428f08f022f230', '0f4317272654459794ab7a70b695e7f1', 9, 'Où se trouve le siège de cette association ?', 'Répondez le plus honnêtement possible : une enquête peut avoir été menée à ce sujet.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('5d4d60a3d36241c1b503f7b62b90398d', '0f4317272654459794ab7a70b695e7f1', 10, 'Pratiquez-vous une religion ?', 'Citez, le cas échéant, la ou les religions que vous pratiquez, en toute honnêteté.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('e96eaf869c15478aaa5ea6829fa35b8b', '0f4317272654459794ab7a70b695e7f1', 11, 'Quels sont vos loisirs ?', 'Citez vos loisirs réels et quotidiens : la marche, la lecture, le foot, la natation, la musique, le cinéma, etc.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c3bfd8ad656f4909bff653b4f13bd62f', '11cdc89a05ba451f838554965bfcac7a', 0, 'Êtes-vous marié(e) ? Avez-vous un(e) compagnon/compagne, mari ou femme ?', 'Si vous êtes célibataire, répondez simplement. Si vous êtes marié(e) ou pacsé(e), répondez oui en précisant depuis combien de temps.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('887f602d072846f39e69d4ced15c6f8c', '11cdc89a05ba451f838554965bfcac7a', 1, 'Votre conjoint(e) vit-il ou vit-elle avec vous ?', 'Répondez oui : votre conjoint(e) doit vivre avec vous en France. Si ce n''est pas le cas, votre demande risque d''être vue comme révélant des attaches à l''étranger — attention à la différence entre résider en France et y être seulement domicilié(e), ce qui n''est pas suffisant pour la naturalisation par décret.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('8c0103d658134f7aaca73d2dfa985667', '11cdc89a05ba451f838554965bfcac7a', 2, 'Quelles activités effectuez-vous avec votre conjoint(e) ?', 'Parlez de vos activités sportives et culturelles, de vos sorties du week-end et de vos vacances communes.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('2af5169bf019452d94fd5c8b85996381', '11cdc89a05ba451f838554965bfcac7a', 3, 'Avez-vous des enfants ? Comptez-vous en avoir prochainement ?', 'Répondez selon votre situation, en précisant que vos enfants sont ou resteront en France.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('d960e8bb0382405797091fa2cb166b0a', '11cdc89a05ba451f838554965bfcac7a', 4, 'Dans le couple, qui s''occupe des enfants et des tâches ménagères ?', 'L''agent cherche à savoir si les tâches sont réparties à part égale entre les parents. Ne dites pas « j''aide ma femme / mon mari », mais plutôt que vous participez ensemble et à part égale aux tâches ménagères et à l''éducation des enfants.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('5f7ed2dbb19440b9adce3fab82bf19ba', '11cdc89a05ba451f838554965bfcac7a', 5, 'Quelle langue utilisez-vous au travail et à la maison ?', 'Répondez que vous utilisez le français pour tous vos échanges, au travail comme dans la vie quotidienne.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f46c5938d3bd4131b39278e620f58ce5', 'f1025be638444aa4b8f98076003ddc74', 0, 'Où avez-vous appris le français ?', 'Citez les lieux réels : à l''école dans votre pays d''origine, dans un centre culturel français, en cours particuliers, en cours en ligne, lors d''un voyage linguistique, etc.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('328fc0142d1741eeaaa53d2cd35b7847', 'e7b0104b8fb3410e8e29ccd06d6a239c', 10, 'En quelle année l''esclavage a-t-il été aboli en France ?', 'Le 27 avril 1848.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('27cf0c13ae014777b7c67485a54f91f7', 'f1025be638444aa4b8f98076003ddc74', 1, 'Pendant combien de temps avez-vous étudié le français ?', 'Répondez selon votre situation (par exemple 2, 5 ou 10 ans). Un niveau minimum B1 est exigé pour réussir l''entretien de naturalisation ; si vous suivez des cours pour progresser vers le B2, mentionnez-le.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f948062754b4468e8841c1ecbf3afbd3', 'f1025be638444aa4b8f98076003ddc74', 2, 'Utilisez-vous la langue française au travail ?', 'Si oui, dites-le simplement. Si non, expliquez pourquoi et mentionnez un projet précis pendant lequel vous avez utilisé le français.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('a861cb0d6a4f41048ca193bface348bd', 'f1025be638444aa4b8f98076003ddc74', 3, 'Parlez-vous d''autres langues ? Lesquelles ?', 'Citez votre langue maternelle ainsi que toutes les autres langues étrangères que vous connaissez, en plus du français.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('01cc178b17f74d32a5304659c68e5253', 'f1025be638444aa4b8f98076003ddc74', 4, 'Quelle langue vous paraît la plus facile ? Pourquoi ?', 'Répondez « le français », car c''est la langue que vous utilisez au quotidien.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c13edf0045684ffbb48500792cff302e', '2ecfd0efbb484bb89c6efe8e5c902b21', 0, 'Citez les trois plus grandes villes françaises.', 'Paris, Lyon et Marseille.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('03dda499482541f992fe0eb93efc0328', '2ecfd0efbb484bb89c6efe8e5c902b21', 1, 'Citez trois départements français.', 'Par exemple le Haut-Rhin, le Bas-Rhin et la Haute-Garonne.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('0c09656be98f48dd867e9ad40c54ccba', '2ecfd0efbb484bb89c6efe8e5c902b21', 2, 'Citez trois départements d''outre-mer.', 'Par exemple la Guadeloupe, la Martinique, la Guyane, Mayotte ou La Réunion.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('aaecc2ebd6434b8b9ea405ac03e8c553', '2ecfd0efbb484bb89c6efe8e5c902b21', 3, 'Citez trois régions françaises.', 'Par exemple l''Île-de-France, la Bretagne, la Normandie, la Corse, les Hauts-de-France, l''Auvergne-Rhône-Alpes, la Provence-Alpes-Côte d''Azur ou l''Occitanie.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('d5485e244bef48799a08504a192a1065', '2ecfd0efbb484bb89c6efe8e5c902b21', 4, 'Énumérez les trois types de collectivités françaises.', 'Les communes (environ 35 000 en France), les régions (13 en métropole, dont la Corse qui est une collectivité territoriale à statut particulier plutôt qu''une région de plein droit, plus les régions d''outre-mer) et les départements (101 au total : 96 en métropole et 5 en outre-mer).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ed3b83dce6ec4c738e4d6e16f4864f43', '2ecfd0efbb484bb89c6efe8e5c902b21', 5, 'Citez des fleuves français que vous connaissez.', 'Par exemple la Loire, le Rhône, la Seine, le Rhin, la Garonne, la Marne ou la Dordogne.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('aeaf87e9b85f4242a8796572c7cb1bfd', '2ecfd0efbb484bb89c6efe8e5c902b21', 6, 'Citez des chaînes de montagnes françaises que vous connaissez.', 'Par exemple le Massif central, les Alpes, les Pyrénées, les Vosges et le Jura.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('05fb29501ac842b2992babfd8b938a1b', '2ecfd0efbb484bb89c6efe8e5c902b21', 7, 'Quel est le point culminant de la France ?', 'Le Mont Blanc, à environ 4 809 mètres d''altitude (l''altitude exacte varie légèrement selon l''épaisseur de la neige). Il se trouve à la frontière entre la France et l''Italie.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('b215b46f30124f66941827127e96b5a8', '2ecfd0efbb484bb89c6efe8e5c902b21', 8, 'Quels sont les pays frontaliers (limitrophes) de la France ?', 'L''Espagne, l''Italie, la Suisse, l''Allemagne, le Luxembourg, Andorre, Monaco et la Belgique.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('de319924af834b6a9a916fa0614b22f4', '2ecfd0efbb484bb89c6efe8e5c902b21', 9, 'Dans quelle région sommes-nous ?', 'Donnez le nom de votre région, par exemple « nous sommes dans la région Île-de-France ».', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c36ba5e3f3ba428b89dae87bf6754d6d', '2ecfd0efbb484bb89c6efe8e5c902b21', 10, 'Dans quel département sommes-nous ?', 'Donnez le nom de votre département, par exemple « nous sommes dans le département du Val-de-Marne ».', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('17183dd6ee644f2689d1958bc820a287', '2ecfd0efbb484bb89c6efe8e5c902b21', 11, 'Qui est le maire de votre commune ?', 'Renseignez-vous avant l''entretien sur le nom de votre maire, son orientation politique et son parti.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1d99f566fff3490d9678a1a4474883ca', 'e7b0104b8fb3410e8e29ccd06d6a239c', 0, 'Citez trois rois de France.', 'Par exemple Charlemagne, François Ier, Henri IV ou Louis XV.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f604ee474389492192e46ac6985af741', 'e7b0104b8fb3410e8e29ccd06d6a239c', 1, 'Citez des reines de France.', 'Par exemple Catherine de Médicis, Aliénor d''Aquitaine, Marie-Antoinette ou Anne d''Autriche.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('d36b019ec62d4a8684f866d1ceffa822', 'e7b0104b8fb3410e8e29ccd06d6a239c', 2, 'En quoi et pourquoi Louis XIV est-il le plus connu ?', 'Louis XIV est le roi de France le plus connu, notamment pour la durée exceptionnelle de son règne, la plus longue de l''histoire de France. Il est aussi le symbole de la monarchie absolue, plus tard combattue par la Révolution française.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f778da2637e144e4b65d30745812b041', 'e7b0104b8fb3410e8e29ccd06d6a239c', 3, 'Qui était le roi de France durant la Révolution française ? Qu''est-il devenu ?', 'Louis XVI. Le peuple s''est révolté contre son pouvoir absolu et a proclamé la République ; la famille royale a été emprisonnée, le roi jugé et condamné à mort, puis guillotiné le 21 janvier 1793.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('aeee672ec627450d83b5dba2fb171f8f', 'e7b0104b8fb3410e8e29ccd06d6a239c', 4, 'À quelle date précise a eu lieu la Révolution française ?', 'Elle a débuté le 5 mai 1789 avec l''ouverture des États généraux et s''est terminée le 9 novembre 1799 avec le coup d''État du 18 brumaire de Napoléon Bonaparte.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('4959bc14d5b645ee9c962f0035399b1d', 'e7b0104b8fb3410e8e29ccd06d6a239c', 5, 'Quel événement de la Révolution française vous a le plus marqué ?', 'Vous pouvez citer par exemple la prise de la Bastille, le 14 juillet 1789, événement inaugural de la Révolution.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('0b904c742dfe48f0be7f1bda4ed7e0df', 'e7b0104b8fb3410e8e29ccd06d6a239c', 6, 'Quelle crise a mené à la Révolution française ?', 'Une crise agricole ayant provoqué une grave crise économique et une forte inflation, dans un contexte de hausse des impôts décidée par le roi de l''époque, Louis XVI.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('fe729168aaef4e3aaa6f9a666f9efddd', 'e7b0104b8fb3410e8e29ccd06d6a239c', 7, 'Quel a été le rôle de la Bastille avant sa démolition ?', 'Elle servait de prison d''État, dans laquelle furent notamment emprisonnées des personnalités comme Voltaire et le marquis de Sade.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('fcf400334c084ca3b53aa6c4f2b65cf7', 'e7b0104b8fb3410e8e29ccd06d6a239c', 8, 'Quand a été adoptée la Déclaration des Droits de l''Homme et du Citoyen ?', 'Le 26 août 1789. C''est l''une des questions les plus fréquentes de l''entretien de naturalisation.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('88291fa21eaf4e2f8e114b2842d0e69b', 'e7b0104b8fb3410e8e29ccd06d6a239c', 9, 'Qui a instauré le Code civil en France ?', 'Napoléon Bonaparte.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('967937dcf24c42c384ee31ca7265138d', '35675b37a2f64a0f9819f152e7abc96f', 0, 'Quelles sont les dates des deux dernières guerres mondiales ?', 'La Première Guerre mondiale : du 28 juillet 1914 au 11 novembre 1918. La Seconde Guerre mondiale : du 1er septembre 1939 au 2 septembre 1945.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('9ec3ec697a1543e7b83a1ae16464daf2', '35675b37a2f64a0f9819f152e7abc96f', 1, 'Quel était le surnom des soldats français durant la Première Guerre mondiale ?', 'On les appelait les « poilus ».', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('994b299d090a493699e97bc3bb1f7990', '35675b37a2f64a0f9819f152e7abc96f', 2, 'Qui étaient les Alliés durant la Première Guerre mondiale ?', 'La France, l''Angleterre, la Russie et les États-Unis.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c24dc74c273244e7908b7a2948373172', '35675b37a2f64a0f9819f152e7abc96f', 3, 'Qui étaient les Alliés durant la Seconde Guerre mondiale ?', 'La France, l''Angleterre, l''URSS (Union soviétique) et les États-Unis.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ed41d96cf838485ea6a934e19257ae10', '35675b37a2f64a0f9819f152e7abc96f', 4, 'Connaissez-vous la bataille de Verdun ?', 'Elle a eu lieu en 1916, entre l''armée française et l''armée allemande, en Lorraine, pendant la Première Guerre mondiale. Elle a fait beaucoup de victimes dans les deux camps, sans vainqueur clair.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f249c20f4ceb423b9858eb768ca36289', '35675b37a2f64a0f9819f152e7abc96f', 5, 'Quand et où a eu lieu le débarquement des Alliés durant la Seconde Guerre mondiale ?', 'Le 6 juin 1944, en Normandie.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('554cf0f95d2f4d9fa6e3d0522d3f5d0a', '35675b37a2f64a0f9819f152e7abc96f', 6, 'Pourquoi le 11 novembre est-il férié ?', 'Le 11 novembre marque la fin de la Première Guerre mondiale : c''est l''armistice, signé en 1918.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('aa25621723d148b19f13cbbc98653102', '35675b37a2f64a0f9819f152e7abc96f', 7, 'Qui est Charles de Gaulle ?', 'Un militaire, résistant et homme politique français, fondateur de la Ve République et l''un des principaux architectes de la Résistance française. Il a été président de la République sous la Ve République, de 1959 à 1969.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('9eb0822bcd884aab835a85ad819d78be', '35675b37a2f64a0f9819f152e7abc96f', 8, 'Quand a été instituée la Ve République ?', 'Par la Constitution du 4 octobre 1958.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('078c42cb2c634ef69e5e523207e16adb', '35675b37a2f64a0f9819f152e7abc96f', 9, 'Quel a été le fait marquant de la Ve République ?', 'Elle a marqué définitivement la séparation entre les pouvoirs exécutif, législatif et judiciaire.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('8378478f9ea44ad586c33983e7c56a1d', '35675b37a2f64a0f9819f152e7abc96f', 10, 'Dans quelle République sommes-nous aujourd''hui ?', 'La Ve République.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('6f5d0bdc9651447e85783e24abfbdbf1', '35675b37a2f64a0f9819f152e7abc96f', 11, 'Quelles sont les dates des précédentes républiques françaises ?', '1re République : 1792-1804. 2e République : 1848-1852. 3e République : 1870-1940. 4e République : 1946-1958. 5e République : depuis 1958.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('6d32d3eda867429296cfa1e2aad926f9', '35675b37a2f64a0f9819f152e7abc96f', 12, 'Qui a instauré la Ve République ?', 'Le général Charles de Gaulle.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('9234bdb7d17e45818e8b5c37191577a3', '61b5b1156e8c444b862f6e122b51f2f0', 0, 'Citez des monuments historiques français que vous connaissez.', 'Par exemple la Tour Eiffel, l''Arc de Triomphe, le château de Versailles, le château de Vincennes, le Louvre, les châteaux de la Loire (dont le château de Chambord) ou le Pont du Gard.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1d82a681b6bd45149cb16ca956215e1e', '61b5b1156e8c444b862f6e122b51f2f0', 1, 'Qui a été à l''origine du château de Versailles ? Et de l''Arc de Triomphe ?', 'Louis XIV pour le château de Versailles ; Napoléon Ier pour l''Arc de Triomphe.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('2da31e9e8bf84b26a5e87935aa0ac8aa', '61b5b1156e8c444b862f6e122b51f2f0', 2, 'Quel est le monument principal en France ?', 'La Tour Eiffel, à Paris.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('65e3536b722b44308a3e6fb98666931c', '61b5b1156e8c444b862f6e122b51f2f0', 3, 'Qui a construit la Tour Eiffel ? Quand, et à quelle occasion ?', 'Gustave Eiffel l''a construite en 1889, à l''occasion de l''Exposition universelle de Paris.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('4ea3157fee5e4912acfd666c844f5c34', '61b5b1156e8c444b862f6e122b51f2f0', 4, 'Quels sont les plats typiques français que vous connaissez ?', 'Par exemple la bouillabaisse, le pot-au-feu, la quiche lorraine, les galettes bretonnes, le steak tartare ou l''aligot.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('99a3acc4e9964fa5958cd415f824e05e', '61b5b1156e8c444b862f6e122b51f2f0', 5, 'Citez des personnages littéraires français célèbres.', 'Par exemple Victor Hugo, Albert Camus ou Alexandre Dumas.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('72755d1d733c40fb9edd44907598293e', '61b5b1156e8c444b862f6e122b51f2f0', 6, 'Citez des peintres français célèbres.', 'Par exemple Cézanne, Delacroix ou Monet.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('b21ae647720d407085cb89c1f0792fb4', '61b5b1156e8c444b862f6e122b51f2f0', 7, 'Citez des personnes naturalisées françaises célèbres.', 'Par exemple Marie Curie ou Joséphine Baker. Attention : on cherche ici des personnes réellement naturalisées, et non des Français d''origine étrangère — Zinedine Zidane ou Jamel Debbouze, par exemple, sont nés français et ne sont pas des personnes naturalisées.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('4d998d3f4a8e4c58b33599775f9ab49c', '61b5b1156e8c444b862f6e122b51f2f0', 8, 'Citez des artistes français connus.', 'Par exemple Berlioz, Joe Dassin, Charles Aznavour ou Gustave Eiffel.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('66195fc0b2d34d45abfcead552e4bba6', '61b5b1156e8c444b862f6e122b51f2f0', 9, 'Citez des écrivains français célèbres.', 'Par exemple Beaumarchais, Molière ou Victor Hugo.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('5bddccf5e51c4860877718d1cab8b2a3', '61b5b1156e8c444b862f6e122b51f2f0', 10, 'Citez des œuvres littéraires françaises célèbres.', 'Par exemple Notre-Dame de Paris, Le Malade imaginaire ou Le Mariage de Figaro.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('a20188fc81084bb6a87a69af9b8244ec', '61b5b1156e8c444b862f6e122b51f2f0', 11, 'Qui a écrit Les Trois Mousquetaires ?', 'Alexandre Dumas, avec la collaboration d''Auguste Maquet.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('fa9c13a108a04422aff018f44f0e366b', '61b5b1156e8c444b862f6e122b51f2f0', 12, 'Qui était Voltaire ?', 'De son vrai nom François-Marie Arouet, Voltaire est un écrivain et philosophe français du XVIIIe siècle.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('3e6eadb157b4484eabdee4b45133d189', '61b5b1156e8c444b862f6e122b51f2f0', 13, 'À quel mouvement Voltaire appartenait-il ?', 'Il appartenait à la philosophie des Lumières, dont il est l''un des représentants les plus connus.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('2d93131480944a56bd3d5ace576c2ba2', '61b5b1156e8c444b862f6e122b51f2f0', 14, 'Citez des philosophes des Lumières que vous connaissez.', 'Par exemple Montesquieu, Voltaire, Diderot, Rousseau, Spinoza ou Descartes.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('3452995d92ba420b95382e5d7a578032', '61b5b1156e8c444b862f6e122b51f2f0', 15, 'Qu''est-ce que la philosophie des Lumières ?', 'Un mouvement culturel, philosophique et intellectuel apparu dans la seconde moitié du XVIIIe siècle, porté par des penseurs comme Voltaire et Rousseau, qui a combattu l''irrationnel et l''obscurantisme et a fortement influencé la Déclaration d''indépendance des États-Unis et la Révolution française.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('e4c27f23e5a4484c95c0c52124dd8a28', '61b5b1156e8c444b862f6e122b51f2f0', 16, 'Connaissez-vous Brigitte Bardot ?', 'Actrice et chanteuse française, icône des années 1960, aujourd''hui surtout connue pour son engagement en faveur de la cause animale (elle a fondé la Fondation Brigitte Bardot).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('a57f6001a2cc43399c879339c70d29bf', '61b5b1156e8c444b862f6e122b51f2f0', 17, 'Citez des chanteurs et chanteuses français connus.', 'Par exemple Dalida, Johnny Hallyday, Charles Aznavour, Georges Brassens ou Claude François.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('839efce980114bcdbc84d280c161fc8c', '61b5b1156e8c444b862f6e122b51f2f0', 18, 'Citez des acteurs et actrices français que vous connaissez.', 'Par exemple Jean Dujardin, Gérard Depardieu ou Marion Cotillard.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1513cd052b7b4eed80c50abdf712b4e7', '61b5b1156e8c444b862f6e122b51f2f0', 19, 'Connaissez-vous des sportifs français célèbres ?', 'Par exemple, en football : Michel Platini, Zinedine Zidane ; en cyclisme : Richard Virenque ; en tennis : Jo-Wilfried Tsonga, Gaël Monfils, Yannick Noah ; en judo : Teddy Riner.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('72776498c0dc495fa5daaa7070c957dc', '61b5b1156e8c444b862f6e122b51f2f0', 20, 'Quel grand événement sportif français connaissez-vous ?', 'Par exemple une épreuve cycliste comme le Tour de France, une épreuve de tennis comme le tournoi de Roland-Garros, ou une course comme le marathon de Paris.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('bfbb4ef88c0d4339becd6de7137420d7', 'f14ec8c4830a454692b7ee693b35686e', 0, 'L''école est-elle obligatoire en France ?', 'Oui, l''instruction est gratuite et obligatoire pour tous les enfants, français et étrangers, de l''âge de 3 ans jusqu''à 16 ans révolus (l''âge minimum a été abaissé de 6 à 3 ans depuis 2019).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('788fc63a30f74c1d864b040b6aa84927', 'f14ec8c4830a454692b7ee693b35686e', 1, 'Depuis quand et par qui l''école est-elle obligatoire en France ?', 'L''instruction est obligatoire depuis le 28 mars 1882, une loi portée par Jules Ferry.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('cf47e3a073da47389e83048700417887', 'f14ec8c4830a454692b7ee693b35686e', 2, 'Les femmes ont-elles le droit de vote en France ? Depuis quand ?', 'Oui, depuis le 21 avril 1944.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c81354c6c48c4f33ac6882ded5c6c5ec', 'f14ec8c4830a454692b7ee693b35686e', 3, 'Quand a eu lieu la séparation de l''Église et de l''État en France ?', 'Par la loi du 9 décembre 1905.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('311d0556199f4ef08bb3f5f0fbdcaddf', 'f14ec8c4830a454692b7ee693b35686e', 4, 'Pourquoi le 1er mai est-il férié ?', 'Parce que l''on y fête la fête du Travail.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('5535cf64269a4970befc94431f1d1728', 'f14ec8c4830a454692b7ee693b35686e', 5, 'Que fait-on le 14 juillet ?', 'C''est la fête nationale française. Le 14 juillet est généralement associé à la prise de la Bastille en 1789, mais commémore dans les faits la Fête de la Fédération du 14 juillet 1790.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('7ae656585a0c47b3a983eab081980d80', 'f14ec8c4830a454692b7ee693b35686e', 6, 'À quelle époque ont été bâties les cathédrales gothiques en France ?', 'Au Moyen Âge.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1c196a9d73d84245864db93fe7e27f19', 'f14ec8c4830a454692b7ee693b35686e', 7, 'Qu''est-ce que l''hôtel de ville ?', 'C''est la mairie principale d''une grande ville ou d''une ville importante.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('6dd4c91287ab47a7a4cecbb4a54c1bfe', 'f14ec8c4830a454692b7ee693b35686e', 8, 'Citez d''anciennes colonies françaises.', 'Par exemple l''Algérie, le Sénégal, le Mali ou la Côte d''Ivoire.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('090c65e5ca544b6a819ec751fd9579bf', 'f14ec8c4830a454692b7ee693b35686e', 9, 'Qu''est-ce que la guerre de Cent Ans ?', 'Un conflit opposant les rois de France et les rois d''Angleterre durant le Moyen Âge. Malgré son nom, il a duré 116 ans (1337-1453).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('57e57fc3367e4b9a8d5acf667496f3d1', '0b63d34fa0074365b5b72198a29da8b3', 0, 'Quelles sont les valeurs, ou la devise, de la République française ?', 'Liberté, Égalité, Fraternité.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('3ed56bc1cd4243c6af9fb40a205d2192', '0b63d34fa0074365b5b72198a29da8b3', 1, 'Si l''on devait ajouter une valeur à la devise, laquelle serait-ce selon vous ?', 'La laïcité.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c07c308de3ea4a45ae3574ae4a3ac14b', '0b63d34fa0074365b5b72198a29da8b3', 2, 'Qu''est-ce que la laïcité ?', 'Elle garantit la liberté de conscience, et donc la liberté de manifester ses croyances ou convictions dans les limites du respect de l''ordre public. Elle implique la neutralité de l''État et l''égalité de tous devant la loi, sans distinction de religion ou de conviction.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('0b23fc22258c4d55821075b10d922ae4', '0b63d34fa0074365b5b72198a29da8b3', 3, 'Avons-nous le droit, en France, de porter des signes religieux dans l''espace public ?', 'Oui, mais pas dans les écoles, collèges et lycées publics.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c6e22d5abeb1411ea31d1cfa4d1273f5', '0b63d34fa0074365b5b72198a29da8b3', 4, 'Qu''est-ce que la loi de 2004 ?', 'Codifiée à l''article L141-5-1 du code de l''éducation, elle stipule que dans les écoles, collèges et lycées publics, le port de signes ou tenues par lesquels les élèves manifestent ostensiblement une appartenance religieuse est interdit.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('15dc02d43e054771b623c090efb76787', '0b63d34fa0074365b5b72198a29da8b3', 5, 'Qu''est-ce que la démocratie, pour vous ?', 'Un système politique dans lequel le peuple est souverain : tous les citoyens participent aux décisions publiques et à la vie politique du pays.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('400196c9cc1849a6923375485afb5a10', '0b63d34fa0074365b5b72198a29da8b3', 6, 'Quelles sont les formes de la démocratie ?', 'La démocratie directe, la démocratie participative et la démocratie représentative.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('8087217fe3bf475bb51974c00bde6986', '0b63d34fa0074365b5b72198a29da8b3', 7, 'Êtes-vous d''accord avec le régime démocratique ?', 'Répondez de façon positive et argumentée : par exemple, oui, absolument.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('7a8609ea5bc04f94968e4c2a4fcaf1f4', '0b63d34fa0074365b5b72198a29da8b3', 8, 'Quelles formes de liberté sont garanties en démocratie ?', 'La liberté de penser, la liberté de croire ou de ne pas croire, et la liberté d''expression.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('41e8614082614c26ad07d0a2045ef450', '0b63d34fa0074365b5b72198a29da8b3', 9, 'Pensez-vous que la liberté d''expression soit absolue ?', 'Non : la liberté d''expression est garantie mais n''est pas absolue, car la liberté des uns s''arrête là où commence celle des autres.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('b31eb7e51d394684b3542a97fec44291', '0b63d34fa0074365b5b72198a29da8b3', 10, 'Quels sont les droits et devoirs du citoyen français ?', 'Droits : voter, circuler, s''exprimer, croire ou ne pas croire en une religion, créer des associations, disposer de son corps, et le droit de propriété. Devoirs : respecter la loi, les droits des autres citoyens et l''environnement, payer ses impôts, et défendre la patrie si elle est menacée.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('36b47e643006403c8b5a936150dece87', '0b63d34fa0074365b5b72198a29da8b3', 11, 'Quels sont les symboles de la République française ?', 'Le drapeau tricolore, la Marseillaise, Marianne, le bonnet phrygien, la devise « Liberté, Égalité, Fraternité », la fleur de lys, et le 14 juillet.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f2b93c6e02664ee1b0becb7f2258f634', '0b63d34fa0074365b5b72198a29da8b3', 12, 'Quelles sont les couleurs du drapeau français ? Que représentent-elles ?', 'Bleu, blanc, rouge. Le bleu et le rouge sont traditionnellement associés aux couleurs de Paris, le blanc à la couleur des rois.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('d0f3db865251410990cbac68a2ace0ca', '0b63d34fa0074365b5b72198a29da8b3', 13, 'Qui est Marianne ?', 'Une figure symbolique de la République française, représentée sous l''apparence d''une femme coiffée d''un bonnet phrygien. Elle incarne la République et ses valeurs : Liberté, Égalité, Fraternité.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f367608ba233481bb9dd1a64a9febd6b', '0b63d34fa0074365b5b72198a29da8b3', 14, 'Quel est l''hymne de la France ? Qui l''a écrit ?', 'La Marseillaise, écrite par Claude Joseph Rouget de Lisle.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('192237713cd94f8daac59f77f8c6c5ed', '0b63d34fa0074365b5b72198a29da8b3', 15, 'À quelle occasion la Marseillaise a-t-elle été écrite ?', 'Dans la nuit du 25 au 26 avril 1792, à la suite de la déclaration de guerre du roi d''Autriche. Elle fut composée à Strasbourg et s''intitulait à l''origine « Chant de guerre pour l''armée du Rhin ».', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('106526fd3b0b404ebc6500e06a180706', '0b63d34fa0074365b5b72198a29da8b3', 16, 'Connaissez-vous le premier couplet de la Marseillaise ?', 'Préparez-le : si l''agent vous le demande, vous devez pouvoir chanter ou réciter le premier couplet.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('481a6750a9e04c40a5259abe22972676', 'a6f176f85a5d4d03af357c27f097b15f', 0, 'Qui a le droit de voter aux élections en France ?', 'Tout citoyen français majeur.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('2152218aca48495f89a3ac67579fd556', 'a6f176f85a5d4d03af357c27f097b15f', 1, 'Quel est l''âge de la majorité en France ?', '18 ans.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('01d9043648084e10a701d601f9f3020c', 'a6f176f85a5d4d03af357c27f097b15f', 2, 'Pour combien de temps, et selon quel mode de scrutin, le président de la République est-il élu ?', 'Il est élu pour un mandat de 5 ans, renouvelable une seule fois, au suffrage universel direct, par un scrutin majoritaire à deux tours.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('e6654af27f474d4e873b5122012dc8cd', 'a6f176f85a5d4d03af357c27f097b15f', 3, 'Qui décide d''octroyer ou non la nationalité française ?', 'Le ministre de l''Intérieur.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('343874d752274e29b250a53cda320216', 'a6f176f85a5d4d03af357c27f097b15f', 4, 'Qu''est-ce que le pouvoir exécutif ? Quel est son rôle ?', 'Le pouvoir incarné par le président de la République et son gouvernement. Son rôle est de mettre en œuvre les lois et de conduire la politique nationale ; il dispose pour cela de l''administration et de la force armée, et peut édicter des règlements.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('5b6b8970b11d4b1498af45568fb50447', 'a6f176f85a5d4d03af357c27f097b15f', 5, 'Qu''est-ce que le pouvoir législatif ? Quel est son rôle ?', 'Il est exercé par les deux chambres du Parlement, le Sénat et l''Assemblée nationale. Il est chargé de la rédaction et de l''adoption des lois, ainsi que du contrôle de l''exécutif.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('cf3ea2b8663b44128cf0826d1e1d32d2', 'a6f176f85a5d4d03af357c27f097b15f', 6, 'Qu''est-ce que le pouvoir judiciaire ? Quel est son rôle ?', 'L''un des trois pouvoirs constituant l''État français, aux côtés des pouvoirs exécutif et législatif, dans le respect du principe de séparation des pouvoirs. Il est entre les mains des juges et des magistrats et a pour rôle de contrôler l''application de la loi et d''en sanctionner le non-respect.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('16f099fbd9a749e29d5068c5221f2ccc', 'a6f176f85a5d4d03af357c27f097b15f', 7, 'Citez les différentes institutions politiques en France.', 'Le pouvoir exécutif, le pouvoir législatif, et le pouvoir judiciaire (exercé par les juges et magistrats).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('6cc40d3663c844a6b8332dd36c9fff7f', 'a6f176f85a5d4d03af357c27f097b15f', 8, 'Citez, dans l''ordre, les présidents de la Ve République.', 'Charles de Gaulle, Georges Pompidou, Valéry Giscard d''Estaing, François Mitterrand, Jacques Chirac, Nicolas Sarkozy, François Hollande, puis Emmanuel Macron.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('776b9c44b1d64725a4811d58ff9e33ca', 'a6f176f85a5d4d03af357c27f097b15f', 9, 'Citez trois anciens Premiers ministres français de la Ve République.', 'Par exemple Édouard Philippe, Dominique de Villepin ou François Fillon.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ddca64fba5614d359b8a6d347fa27bd0', 'a6f176f85a5d4d03af357c27f097b15f', 10, 'Qui nomme les ministres et secrétaires d''État ?', 'Le Premier ministre.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ac5f9332e21647db8bad9fd88688cb32', 'a6f176f85a5d4d03af357c27f097b15f', 11, 'Qui nomme le Premier ministre de la France ?', 'Le président de la République.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('61cca18c33234703a8114e84fd38c55f', 'a6f176f85a5d4d03af357c27f097b15f', 12, 'Où se trouvent les bureaux du Premier ministre ?', 'À l''Hôtel Matignon, à Paris.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('88d7d46c69484874924b691273ecd062', 'a6f176f85a5d4d03af357c27f097b15f', 13, 'Où se trouve le siège de la présidence de la République ?', 'Le palais de l''Élysée.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('76ce89e120ff4842aadede9bea52eb60', 'a6f176f85a5d4d03af357c27f097b15f', 14, 'Constitutionnellement, qui dirige le pays si le président de la République décède ?', 'Le président du Sénat assure l''intérim.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('40c676ee1faa4f7098b30390a9181b0a', 'a6f176f85a5d4d03af357c27f097b15f', 15, 'Qu''est-ce que le Conseil constitutionnel ?', 'Une institution française créée par la Constitution de la Ve République du 4 octobre 1958. Il se prononce sur la conformité à la Constitution des lois et de certains règlements, et veille à la régularité des élections nationales et des référendums.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('76fe332aef9043ca8dd6e8cc675be298', 'a6f176f85a5d4d03af357c27f097b15f', 16, 'Savez-vous ce qu''est la cohabitation politique ? Donnez un exemple.', 'La cohabitation désigne la coexistence institutionnelle entre un président de la République et un Premier ministre issu d''une majorité parlementaire politiquement opposée. Exemples historiques : Mitterrand (PS) avec Chirac (RPR), puis Chirac (RPR) avec Jospin (PS).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('982fa509eafd47a69eaba39f421df25d', 'a6f176f85a5d4d03af357c27f097b15f', 17, 'Quel ministère gère les relations entre l''État et les institutions religieuses ?', 'Le ministère de l''Intérieur, via le bureau central des cultes.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('4805dfeac659445a9ac51b54af4199ee', 'e6e1553ac340426ca5b50148678444cc', 0, 'Qu''est-ce que le Parlement ?', 'Une assemblée élue par le peuple qui assure sa représentation. Il est composé de deux chambres : la chambre haute (le Sénat) et la chambre basse (l''Assemblée nationale).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('08bdfeffdb0e4896940fea3abfd21198', 'e6e1553ac340426ca5b50148678444cc', 1, 'Quel est le rôle exact du Parlement ?', 'Il revoit, corrige et vote les lois : il détient le pouvoir législatif.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('6acbc555685d4fa9a95042b8a3331bad', 'e6e1553ac340426ca5b50148678444cc', 2, 'Qu''est-ce que la chambre basse ?', 'C''est l''Assemblée nationale, où siègent les députés.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('d4672757e69d411eb371d25b25c59add', 'e6e1553ac340426ca5b50148678444cc', 3, 'Qu''est-ce que la chambre haute ?', 'C''est le Sénat, où siègent les sénateurs.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('99ad63e8f9424b689a9d21f1267b1369', 'e6e1553ac340426ca5b50148678444cc', 4, 'Qu''est-ce que le Sénat ?', 'La chambre haute du Parlement français. Il détient le pouvoir législatif conjointement avec l''Assemblée nationale.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('59fbd67ad27b4e668c125656b18ffc00', 'e6e1553ac340426ca5b50148678444cc', 5, 'Comment sont élus les députés ?', 'Au suffrage universel direct, selon un scrutin uninominal majoritaire à deux tours.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('55e5d579840042209bc1f2653b8a003b', 'e6e1553ac340426ca5b50148678444cc', 6, 'Combien de temps dure le mandat d''un député ?', '5 ans.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('2560cbd46cb347d6ad545462d231621a', 'e6e1553ac340426ca5b50148678444cc', 7, 'Comment sont élus les sénateurs ?', 'Au suffrage universel indirect, par un collège d''environ 150 000 grands électeurs (maires, conseillers généraux, etc.).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('a5a3f76a4b424be4a326a5a1aecf7b98', 'e6e1553ac340426ca5b50148678444cc', 8, 'Pour combien d''années sont élus les sénateurs ?', 'Le Sénat est renouvelé par moitié tous les 3 ans ; la durée totale du mandat sénatorial est donc de 6 ans.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('0cb56fd79dad44af901cca193a21b644', 'e6e1553ac340426ca5b50148678444cc', 9, 'Quelle est la différence entre un député et un sénateur ?', 'Comme les députés, les sénateurs examinent et votent les lois et contrôlent l''action du gouvernement. Mais à la différence de l''Assemblée nationale, le Sénat défend en plus les intérêts des communes, départements et régions — ce que l''on appelle les collectivités territoriales.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('fc9d7b1d3c8646d2a65d7a2b9237d47e', 'b0c2b7456ed34569a08c9b7c21701bc9', 0, 'Quelle est la monnaie actuelle de la France ?', 'L''euro.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('b231c47c1354482e85b1d29b9d245d57', 'b0c2b7456ed34569a08c9b7c21701bc9', 1, 'Quelle est la devise de l''Union européenne ?', '« Unie dans la diversité ».', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('6a865f0d490b478888f96a4ad8938c37', 'b0c2b7456ed34569a08c9b7c21701bc9', 2, 'Connaissez-vous l''hymne de l''Union européenne ?', 'C''est l''Ode à la joie, de Beethoven.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f6fc8a1c91674c8289577e32281fa566', 'b0c2b7456ed34569a08c9b7c21701bc9', 3, 'Combien de pays compte l''Union européenne ?', '27 États membres, depuis que le Royaume-Uni l''a quittée en 2020 (le Brexit).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1912ffa2cefd42a7876ad35dc213e2a0', 'b0c2b7456ed34569a08c9b7c21701bc9', 4, 'Dans quel intérêt les pays européens rejoignent-ils l''Union européenne ?', 'Pour la liberté de circuler dans l''espace Schengen, une monnaie unique et forte (l''euro), l''union politique et financière, et le partage de valeurs démocratiques communes.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('c4b1b818b10a4aadba092dce9bad92e3', 'b0c2b7456ed34569a08c9b7c21701bc9', 5, 'Où se trouve le siège du Parlement européen ?', 'À Strasbourg, en France.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('4f17f211a5a2480e8ed63004d3243e30', 'b0c2b7456ed34569a08c9b7c21701bc9', 6, 'Où se trouve le siège de la Commission européenne ?', 'À Bruxelles, en Belgique.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('fa9670b831a248b7a2bf8ae790eec626', 'b0c2b7456ed34569a08c9b7c21701bc9', 7, 'Combien d''étoiles le drapeau européen comporte-t-il ? Que symbolisent-elles ?', '12 étoiles disposées en cercle, symbolisant les idéaux d''unité, de solidarité et d''harmonie entre les peuples européens (ce nombre est fixe et ne dépend pas du nombre d''États membres).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('21c8054d16e9491491ecc3d5c1a97da0', 'b0c2b7456ed34569a08c9b7c21701bc9', 8, 'Que représente la journée du 9 mai ?', 'C''est la Journée de l''Europe.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('574a2f90c8db4f678ab43eb74a472ebb', 'b0c2b7456ed34569a08c9b7c21701bc9', 9, 'Quels sont les symboles de l''Union européenne ?', 'La monnaie européenne (l''euro), le drapeau européen, la devise de l''Europe, l''hymne européen, et la Journée de l''Europe (le 9 mai).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('cd6acdc13c784b8ba54c437654bdd068', 'b0c2b7456ed34569a08c9b7c21701bc9', 10, 'Que connaissez-vous du traité de Rome ? Quand a-t-il eu lieu ?', 'Le 25 mars 1957, l''Allemagne, la Belgique, la France, l''Italie, le Luxembourg et les Pays-Bas signent à Rome deux traités : le premier crée la Communauté économique européenne (CEE), le second la Communauté européenne de l''énergie atomique (Euratom).', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f3455aea0aea41d5aecffd1d6a619bf2', 'b0c2b7456ed34569a08c9b7c21701bc9', 11, 'Depuis quand les citoyens français sont-ils européens ?', 'Depuis 1992, avec le traité de Maastricht.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('488acd2763894aaeb5e1de2d18ab4c48', '272e16b0924a4dbe834db204e25ffd27', 0, 'Qui est Jeanne d''Arc ?', 'Une jeune paysanne française qui a conduit les troupes françaises à la libération d''une partie du territoire durant la guerre de Cent Ans.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1d7286e0162748fd9ade5fc44f6062bf', '272e16b0924a4dbe834db204e25ffd27', 1, 'Qu''est-ce que la loi Veil ? Que pensez-vous de cette loi ?', 'C''est la loi encadrant l''interruption volontaire de grossesse, préparée par la ministre Simone Veil et votée le 17 janvier 1975. C''est une mesure importante qui garantit aux femmes le droit de disposer de leur corps.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('3a7ccb5d47ed413c88e51ba7543c11ac', '272e16b0924a4dbe834db204e25ffd27', 2, 'Que pensez-vous de la parité homme-femme ? Est-elle atteinte dans tous les domaines ?', 'Les femmes et les hommes sont égaux et doivent avoir les mêmes droits et obligations ; cette parité est garantie par l''article 1er de la Constitution. Elle n''est cependant pas encore atteinte dans tous les domaines, notamment pour l''égalité salariale.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ef75aeef294e4dba87d986629f17f298', '272e16b0924a4dbe834db204e25ffd27', 3, 'Qui a le droit d''accéder à l''emploi public en France ?', 'Tous les citoyens ont le droit d''accéder aux emplois publics.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('84e80a0d1e9a4f839806ec491946a53c', '272e16b0924a4dbe834db204e25ffd27', 4, 'En cas de conflit armé, qui peut être appelé à défendre la patrie ?', 'Tout citoyen de plus de 16 ans peut être appelé à défendre la patrie.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('ab1867103ee9435bba0892e8f1f513e5', '272e16b0924a4dbe834db204e25ffd27', 5, 'Qu''est-ce que le système de sécurité sociale ? Par qui est-il financé ?', 'Un ensemble d''institutions dont la fonction est de protéger les individus contre les conséquences de divers risques sociaux. Il est financé par les entreprises et les personnes qui travaillent — c''est une application du principe de fraternité.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('1aaacc04b70d44d6865a2c5ec45b67db', '272e16b0924a4dbe834db204e25ffd27', 6, 'Qui finance les services publics ?', 'Les personnes qui travaillent, à travers les impôts.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('233bcd5a410144fdac79837233f07b26', '272e16b0924a4dbe834db204e25ffd27', 7, 'Êtes-vous obligé(e) de payer vos impôts en France ?', 'Oui, c''est une question piège fréquente : payer ses impôts est une obligation une fois la nationalité française obtenue.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('30a1fcecc51446b3b69e6e8b422b36b8', '272e16b0924a4dbe834db204e25ffd27', 8, 'Une fois la nationalité française obtenue, comptez-vous vivre en France ?', 'Encore une question piège : répondez que vous obtenez la nationalité française pour vivre principalement en France.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('9b9f94c44e674ed5ba2058d1b4f14918', '272e16b0924a4dbe834db204e25ffd27', 9, 'Les citoyens sont-ils toujours satisfaits des choix du gouvernement ? Comment manifestent-ils leur désaccord ?', 'Non, les citoyens ne sont pas toujours d''accord avec les décisions du gouvernement. Ils manifestent leur désaccord en organisant des manifestations, en faisant grève, ou par toute autre méthode pacifique et légale.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('f7ec4ef7892941b38c74232899f2c84b', '272e16b0924a4dbe834db204e25ffd27', 10, 'Qu''est-ce que la discrimination, pour vous ? Est-elle légale en France ?', 'C''est par exemple refuser de recruter quelqu''un en raison de son origine, de son appartenance ethnique ou religieuse, ou de son sexe — le seul critère d''embauche doit être la compétence. La discrimination est illégale en France : c''est un délit passible de sanctions judiciaires.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('7594dbdcf2764782a09fcfdb0ce1ae7e', '272e16b0924a4dbe834db204e25ffd27', 11, 'Qu''est-ce que les élections municipales ?', 'Des élections qui permettent d''élire les membres du conseil municipal de chaque commune (les conseillers municipaux), qui élisent ensuite le maire et ses adjoints.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('b6d30f0b27f64267a3e0529c76851254', '272e16b0924a4dbe834db204e25ffd27', 12, 'Citez des femmes politiques françaises que vous connaissez.', 'Par exemple Simone Veil, Ségolène Royal ou Élisabeth Borne.', NULL, NULL, NULL, '2026-07-03T14:37:01Z');
INSERT INTO public.challenge_items (item_id, deck_id, "position", front, back, example, media_url, options, created_at_utc) VALUES ('4548ecbd56ea4d74bce80f352c521a69', 'c7d9b857c34a463e9562673c29a7eb8d', 0, 'کدام عبارت درست است؟ «پسر بزرگ» (grand + garçon)', 'un grand garçon', NULL, NULL, '["un gar\u00e7on grand", "un grand gar\u00e7on", "une grande gar\u00e7on", "un gar\u00e7on grande"]', '2026-07-13T13:32:06Z');
