INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('8a6d155ee61e445dbe541ddc6cef46a6', '108648163', '9e61cf44771c49bc9be324dbf5212dc7', 'vocab', '{"back": "Ensemble d''êtres vivants qui peuvent se reproduire entre eux ; catégorie.", "front": "une espèce"}', 'une espece', 'vocab.md', '2026-08-24 15:44:29.764715+00', '2026-08-24 16:06:22.553861+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('7955d50f86da4d90b37c9c2525a7eb10', '108648163', 'eb571bb4c9a34490ad40f39402b363ab', 'grammar', '{"back": "Pronom relatif qui remplace un complément introduit par **de**. Le verbe ou l''adjectif de la relative se construit toujours avec *de*.", "front": "**dont**", "example": "c''est le plat **dont** j''ai envie *(avoir envie **de**)* · c''est la personne **dont** je vous ai déjà parlé *(parler **de**)* · c''est la situation **dont** je suis satisfait *(être satisfait **de**)* · c''est le stylo **dont** j''ai besoin *(avoir besoin **de**)* — cf. « de ce stylo-là »"}', '**dont**', 'vocab.md', '2026-08-24 15:44:29.780058+00', '2026-08-24 16:06:22.578263+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('55a82987e6e04dbb8a2cf813fbadbbb7', '108648163', 'eb571bb4c9a34490ad40f39402b363ab', 'grammar', '{"back": "Au pluriel, quand l''adjectif est placé **avant** le nom, *des* devient *de*.", "front": "**des → de** devant un adjectif", "example": "de jolies fleurs · de nouveaux films · de nouvelles séries *(mais : des films nouveaux — adjectif après le nom)*"}', '**des → de** devant un adjectif', 'vocab.md', '2026-08-24 15:44:29.794435+00', '2026-08-24 16:06:22.622165+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('0e022505a2994c3cb9b74af698737c64', '108648163', 'eb571bb4c9a34490ad40f39402b363ab', 'grammar', '{"back": "*Avant* + **nom** ; *avant de* + **infinitif**.", "front": "**avant de** + infinitif", "example": "avant le repas · avant **de** partir"}', '**avant de** + infinitif', 'vocab.md', '2026-08-24 15:44:29.816213+00', '2026-08-24 16:06:22.652384+00');
