INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('de112e0512c1476fb5e4fec983ff2ce4', '108648163', '73e551e2c14f4f3a9d52c0337137fa6b', 'vocab', '{"back": "Couvrir d''eau ; au figuré, submerger par une trop grande quantité.", "front": "inonder", "example": "N''inondez pas vos amis de photos de vacances.", "source_page": "26"}', 'inonder', 'vocab.md', '2026-08-24 15:44:29.174935+00', '2026-08-24 21:38:58.929536+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('db65821316d24cc9afbeebcc1d517132', '108648163', '73e551e2c14f4f3a9d52c0337137fa6b', 'vocab', '{"back": "Fait de ne pas réussir ; un revers. Au pluriel, <b>les échecs</b> désignent le jeu.", "front": "un échec", "example": "Après cet échec, il a tout recommencé. — Il joue aux échecs.", "note_fa": "همینطور شطرنج", "source_page": "16"}', 'un echec', 'vocab.md', '2026-08-24 15:44:28.872824+00', '2026-08-24 21:38:58.992498+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('20670e65e60049e1ae275d2b8b8d09a7', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Soutien apporté à qqn. <i>Venir en appui de qqn ; apporter son appui.</i>", "front": "un appui", "example": "d''agriculteurs qui se sont portés en appui des pompiers et qui ont apporté"}', 'un appui', 'language-reactor', '2026-08-25 12:00:33.769411+00', '2026-08-25 12:00:33.769411+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('364571ee5bd34db2a58cb2530c4ab6d5', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Finir par être du même avis. <i>Distinct de « tomber » = chuter.</i>", "front": "tomber d''accord (avec qqn)", "example": "monde peut tomber d''accord avec vous sur la nécessité de faire attention à notre"}', 'tomber d''accord (avec qqn)', 'language-reactor', '2026-08-25 12:00:33.853634+00', '2026-08-25 12:00:33.853634+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('7259dad700d74bf29329ed3c3d8cc9f7', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "De manière intense, en profondeur. <i>La société a profondément changé.</i>", "front": "profondément", "example": "profondément changé. On n plus aujourd''hui à l''heure de la"}', 'profondement', 'language-reactor', '2026-08-25 12:00:33.875074+00', '2026-08-25 12:00:33.875074+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('e4fc8cfd1e87425e8491c768e4f18e3f', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Écart, différence entre deux choses qui devraient correspondre. <i>Un décalage entre le discours et la réalité.</i>", "front": "un décalage", "example": "Il y a il y a un profond décalage euh entre une vie politique à Paris qui"}', 'un decalage', 'language-reactor', '2026-08-25 12:00:33.902423+00', '2026-08-25 12:00:33.902423+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('d641d4419add46b296916aa35e59be77', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Qui concerne la campagne. <i>Contraire : urbain. Les territoires ruraux.</i>", "front": "rural, rurale", "example": "je suis beaucoup sur le terrain, en particulier dans les territoires ruraux."}', 'rural, rurale', 'language-reactor', '2026-08-25 12:00:33.922847+00', '2026-08-25 12:00:33.922847+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('ff7f87e4fe134325bb0c7dc59c50bd45', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Période de dix ans.", "front": "une décennie", "example": "ce que disent les scientifiques depuis des décennies. La condition à mes yeux"}', 'une decennie', 'language-reactor', '2026-08-25 12:00:33.951821+00', '2026-08-25 12:00:33.951821+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('bf09137c2ce84138bf109e4bdecf7ad5', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Rendre plus grave, empirer. <i>Aggraver les causes d''un problème.</i>", "front": "aggraver", "example": "d''aggraver les causes euh du problème. Il reste profondément euh euh sur une"}', 'aggraver', 'language-reactor', '2026-08-25 12:00:33.967936+00', '2026-08-25 12:00:33.967936+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('52f39c2e46b6445cb00eac96bf108666', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Fait de perdre qqch. <i>La perte de la biodiversité.</i>", "front": "une perte", "example": "l''effondrement, la perte de la biodiversité, c''est devenu un enjeu de"}', 'une perte', 'language-reactor', '2026-08-25 12:00:33.980726+00', '2026-08-25 12:00:33.980726+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('40f9b1cee84f42ea84048eb4d12c90c2', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Ce que l''on peut gagner ou perdre ; question importante en débat. <i>Un enjeu majeur.</i>", "front": "un enjeu", "example": "va devenir un de nos enjeux majeurs ? Vous allez pas me dire le contraire,"}', 'un enjeu', 'language-reactor', '2026-08-25 12:00:34.003308+00', '2026-08-25 12:00:34.003308+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('5e890003aac248689cc7214c8bd6351e', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Résultat chiffré ou évaluation d''une action, d''une période, d''un mandat. <i>Tirer un bilan ; le bilan d''un gouvernement.</i>", "front": "un bilan", "example": "Donc Édouard Philippe peut promettre ce qu''il veut. Il a un bilan, celui du"}', 'un bilan', 'language-reactor', '2026-08-25 12:00:34.031033+00', '2026-08-25 12:00:34.031033+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('18d40b1568634baea8082880183b4e96', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "S''engager à faire qqch ; assurer que qqch aura lieu. <i>Promettre qqch à qqn.</i>", "front": "promettre", "example": "Donc Édouard Philippe peut promettre ce qu''il veut. Il a un bilan, celui du"}', 'promettre', 'language-reactor', '2026-08-25 12:00:34.04711+00', '2026-08-25 12:00:34.04711+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('db2368f967f441e6b4690f20f6a7cc55', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Diminuer, devenir ou rendre moins élevé. <i>Les salaires ont baissé.</i>", "front": "baisser", "example": "salaire des enseignants a baissé. Donc le temps de campagne et le temps de des"}', 'baisser', 'language-reactor', '2026-08-25 12:00:34.064019+00', '2026-08-25 12:00:34.064019+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('db22a890b69a401ba11bc715280b733b', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Que l''on ne peut pas accepter ; intolérable.", "front": "inadmissible", "example": "retranscrite en direct à la télé ? Ça c''est inadmissible. C''est dénoncé"}', 'inadmissible', 'language-reactor', '2026-08-25 12:00:34.079859+00', '2026-08-25 12:00:34.079859+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('b388b40902974bd3933b8c0178f3d09a', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Ici, sens juridique : reporter une audience à une date ultérieure. <i>Signifie aussi congédier qqn, ou lui retourner qqch.</i>", "front": "renvoyer", "example": "que cette audience soit renvoyée, c''est une victoire euh euh pour Rimaastan et"}', 'renvoyer', 'language-reactor', '2026-08-25 12:00:34.090696+00', '2026-08-25 12:00:34.090696+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('7829aa7d753b4872bbfbc551eeb76248', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Rendre ordinaire ; faire paraître normal ce qui devrait choquer.", "front": "banaliser", "example": "discours qui banalisent la violence d''une certaine façon ? D''abord, le fait"}', 'banaliser', 'language-reactor', '2026-08-25 12:00:34.108509+00', '2026-08-25 12:00:34.108509+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('57b64b18213f4da997c9acbf6e2da2d9', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Danger grave. <i>Au péril de sa vie</i> = en risquant sa vie.", "front": "le péril", "example": "de l''été, qui parfois au péril de leur vie ont été en première ligne pour"}', 'le peril', 'language-reactor', '2026-08-25 12:00:34.13354+00', '2026-08-25 12:00:34.13354+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('fc3023766be44b4d91b27bcff9e4fbf6', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Désirer, souhaiter. <i>« J''ai envie de dire » sert surtout, à l''oral, à atténuer ce qui suit.</i>", "front": "avoir envie de", "example": "conscription écologique, j''ai envie de dire, qui existe déjà puisque les"}', 'avoir envie de', 'language-reactor', '2026-08-25 12:00:34.157406+00', '2026-08-25 12:00:34.157406+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('b29b60e384904c939815fe6957fb250f', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Ici : zone géographique formant un ensemble. <i>Un bassin de population, un bassin d''emploi.</i>", "front": "un bassin", "example": "pèse sur des bassins entiers de population. Mais Jean-Luc Mélenchon ne"}', 'un bassin', 'language-reactor', '2026-08-25 12:00:34.186542+00', '2026-08-25 12:00:34.186542+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('cd1b945c5ea24b2aa82a7a508fdebce8', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Qui vend des produits à l''étranger. <i>La France est exportatrice nette d''électricité.</i>", "front": "exportateur, exportatrice", "example": "énergie stable alors que la France reste exportatrice hein, nette d''électricité."}', 'exportateur, exportatrice', 'language-reactor', '2026-08-25 12:00:34.208045+00', '2026-08-25 12:00:34.208045+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('6e1df8e4e58741d98db132890c3eba33', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Enrôlement obligatoire des citoyens dans l''armée. <i>Ici employé par analogie : « la conscription écologique ».</i>", "front": "la conscription", "example": "ont été balayés dès le premier tour. La conscription écologique, on en a"}', 'la conscription', 'language-reactor', '2026-08-25 12:00:34.24529+00', '2026-08-25 12:00:34.24529+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('e2f83de8a69b4a13b60f9914f40a67a7', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Ce qui se passe réellement, caché derrière les apparences.", "front": "le dessous des cartes", "example": "permanente contre la France soumise. Ça c''est le dessous des cartes. Mais le"}', 'le dessous des cartes', 'language-reactor', '2026-08-25 12:00:34.270952+00', '2026-08-25 12:00:34.270952+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('a03ad714724c49e380675ba86daca62f', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Supporter qqch que l''on n''a pas choisi. <i>Subir une attaque, subir des critiques.</i>", "front": "subir", "example": "est accusé, il est accusé, il a subi depuis qu''il a été élèire et tout cela"}', 'subir', 'language-reactor', '2026-08-25 12:00:34.296876+00', '2026-08-25 12:00:34.296876+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('cedb540a5169492caa7c62e1be0b0396', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Fait de perdre une élection, une bataille. <i>Contraire : la victoire.</i>", "front": "la défaite", "example": "pas digéré la défaite et que la machine à remonter le temps n''existe pas"}', 'la defaite', 'language-reactor', '2026-08-25 12:00:34.317733+00', '2026-08-25 12:00:34.317733+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('fe59c868745c4cebaacfcf398b1e42b8', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Démarche par laquelle on signale une infraction à la justice. <i>Porter plainte, déposer une plainte.</i>", "front": "une plainte", "example": "d''élu. Une enquête a été ouverte par des plaintes après des plaintes de la de"}', 'une plainte', 'language-reactor', '2026-08-25 12:00:34.341286+00', '2026-08-25 12:00:34.341286+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('df7edab81016433c93f0d0adfa252a6a', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Recherche méthodique de faits — judiciaire, policière ou journalistique.", "front": "une enquête", "example": "enquête du parquet national financier et sa réaction sur les réseaux sociaux."}', 'une enquete', 'language-reactor', '2026-08-25 12:00:34.366974+00', '2026-08-25 12:00:34.366974+00');
INSERT INTO public.flashcard_note (note_id, user_id, deck_id, note_type, fields, source_key, source, created_at, updated_at) VALUES ('afbc36334cc548f492d8441aed5db74b', '108648163', 'c1804a3d9b6b4dfc9b02ba145a3004bc', 'vocab', '{"back": "Qui n''est pas digne de ; qui déshonore. <i>C''est indigne d''un candidat.</i>", "front": "indigne (de)", "example": "c''est indigne je crois d''un candidat de la République qui se dit du camp"}', 'indigne (de)', 'language-reactor', '2026-08-25 12:00:34.378822+00', '2026-08-25 12:00:34.378822+00');
